function firstDayBeenInAllRooms(nextVisit) {
  const MOD = 1e9 + 7;
  const n = nextVisit.length;
  const dp = new Array(n).fill(0);

  for (let i = 0; i < n - 1; i++) {
    const back = nextVisit[i];
    const loop = (dp[i] - dp[back] + MOD) % MOD;
    dp[i + 1] = (dp[i] + loop + 2) % MOD;
  }
  return dp[n - 1];
}

