function firstDayBeenInAllRooms(nextVisit) {
  const n = nextVisit.length;
  const visits = new Array(n).fill(0);
  let seen = 0;
  let room = 0;
  for (let day = 0; ; day++) {
    if (visits[room] === 0) seen++;
    visits[room]++;
    if (seen === n) return day % 1000000007;
    room = visits[room] % 2 === 1 ? nextVisit[room] : (room + 1) % n;
  }
}

