function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 2 + Math.floor(rand() * 9);
  const style = rand();
  const nextVisit = [];
  for (let i = 0; i < n; i++) {
    if (style < 0.15) nextVisit.push(0);
    else if (style < 0.3) nextVisit.push(i);
    else if (style < 0.5) nextVisit.push(Math.max(0, i - Math.floor(rand() * 3)));
    else nextVisit.push(Math.floor(rand() * (i + 1)));
  }
  return [nextVisit];
}
